import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, Wave 5 rollout.
 *
 * Real pricing/metadata/JSON-LD are unchanged from the previous hand-rolled
 * GameLandingPage version of this page. The plan figures (4 GB $9.99/10 players,
 * 8 GB $16.99/20 players popular) already matched the PREVIEW_GAMES.valheim demo
 * data exactly, so no price override was needed — same situation as
 * rust-server-hosting/page.tsx.
 *
 * The FAQ section below is carried over verbatim from the previous page (same
 * copy, same JSON-LD) since GameLandingCombined doesn't render its own
 * FAQ/related sections. The "guides" links from the old page are folded into
 * Related since there were only two and no dedicated Guides section pattern
 * was used elsewhere for a game this size.
 */

export const metadata: Metadata = {
  title: "Valheim Server Hosting — Crossplay & Mods, Instant Setup",
  description:
    "Valheim server hosting from $9.99/mo. Dedicated worlds with crossplay, BepInEx mod support, full file access and instant setup on a low-latency network. Scale anytime.",
  alternates: { canonical: "/valheim-server-hosting" },
  openGraph: {
    type: "article",
    title: "Valheim Server Hosting — Crossplay & Mods, Instant Setup",
    description:
      "Managed Valheim hosting: dedicated worlds, crossplay, BepInEx mods, full file access and instant setup. From $9.99/mo.",
    url: `${APP_URL}/valheim-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.valheim;

const FAQ = [
  {
    q: "How much RAM does a Valheim server need?",
    a: "Valheim is fairly light: 4 GB comfortably runs a dedicated world for up to about 10 Vikings, and 8 GB gives you headroom for a bigger group, mods, and sprawling bases. Our 4 GB and 8 GB plans cover both, and you can scale up any time.",
  },
  {
    q: "Can I enable crossplay so Xbox and Game Pass players can join?",
    a: "Yes. Valheim supports crossplay via the -crossplay launch flag, which we can enable so PC, Xbox, and Game Pass players share the same world using a join code.",
  },
  {
    q: "What ports does Valheim use?",
    a: "Valheim uses UDP ports 2456–2458. On a managed Nxeon server those are opened for you and the connect details are provided automatically.",
  },
  {
    q: "Can I add mods like BepInEx or Valheim Plus?",
    a: "Absolutely. Full file access lets you install BepInEx and mods such as Valheim Plus, then upload your config. Note that players generally need the same client-side mods to connect.",
  },
  {
    q: "How quickly is my server ready?",
    a: "Setup is instant — your Valheim world is provisioned and online within minutes of ordering, with the connect string ready to share.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "Palworld server hosting", href: "/palworld-server-hosting" },
  { label: "Enshrouded server hosting", href: "/enshrouded-server-hosting" },
  { label: "Gaming VPS", href: "/gaming-vps" },
  { label: "Pricing", href: "/pricing" },
];

export default function ValheimServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon Valheim Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>
    </>
  );
}

