 *     required to visibly label it as illustrative/example content.
 */

export type PreviewPlan = {
  id: string;
  /** Short tier label, e.g. "Wipe" / "Community". */
  tier: string;
  /** RAM headline, e.g. "6 GB". */
  ram: string;
  /** Displayed price, e.g. "$17.99". Rendered with a trailing "/mo". */
  price: string;
  /** Right-aligned spec meta, e.g. "60 slots" or "4 vCPU · 120 GB NVMe". */
  meta: string;
  /**
   * Advertised player-slot capacity for this plan, when it has one. Drives the
   * interactive pricing configurator's player-count → plan matching. Omitted for
   * VPS-style plans (e.g. Satisfactory) that are sized by RAM rather than slots —
   * those fall back to the fitted RAM curve in lib/game-player-recommend.
   */
  slots?: number;
  blurb: string;
  popular?: boolean;
  features: string[];
};

/** Icon keys resolved to real <Icon*> components inside the client kit. */
