    "Managed ARK: Survival Evolved server hosting from $14.99/mo. Full FTP access, your own admin password, and instant setup on a low-latency Singapore network.",
  alternates: { canonical: "/ark-server-hosting" },
  openGraph: {
    type: "article",
    title: "ARK: Survival Evolved Server Hosting — Instant Setup",
    description:
      "Managed ARK: Survival Evolved hosting: full FTP access, your own admin password, and instant setup on a low-latency Singapore network. From $14.99/mo.",
    url: `${APP_URL}/ark-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.ark;

const FAQ = [
  {
    q: "Is this ARK: Survival Evolved or ARK: Survival Ascended?",
    a: "This page is the original ARK: Survival Evolved (2015, Steam app 376030). Survival Ascended is Studio Wildcard's separate Unreal Engine 5 remake, hosted on its own plans — see our ARK: Survival Ascended hosting page if that's the one you want.",
  },
  {
    q: "How much RAM does an ARK: Survival Evolved server need?",
    a: "8 GB comfortably runs a small tribe on a single map, 16 GB is the recommended baseline for a fuller 50-slot tribe server, and 32 GB gives a busy multi-tribe alliance server room to breathe. Our three plans map directly to those tiers.",
  },
  {
    q: "Can I install mods?",
    a: "Yes. Full FTP file access lets you upload mods and edit GameUserSettings.ini and Game.ini directly to tune taming rates, difficulty, and mod lists — no host-imposed limits.",
  },
  {
    q: "What ports does ARK: Survival Evolved use?",
    a: "The game ports are 7777 and 7778 (UDP), with an RCON/query port on 27020 (TCP). On a managed Nxeon server those are opened for you and the connect details are provided automatically.",
  },
  {
    q: "Is this managed, or do I set it up myself?",
    a: "Fully managed one-click hosting — no SteamCMD or server install to run yourself. Order a plan and it's provisioned and online in minutes, with your admin password ready to set and full FTP access from the start.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "ARK: Survival Ascended hosting", href: "/ark-survival-ascended-server-hosting" },
  { label: "Conan Exiles server hosting", href: "/conan-exiles-server-hosting" },
  { label: "Gaming VPS", href: "/gaming-vps" },
  { label: "Pricing", href: "/pricing" },
];

export default function ArkServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon ARK: Survival Evolved Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
